//! Team plans: the orchestrator's structured breakdown of a request into agents. A plan is
//! generated by `claude -p` with a JSON schema, validated here, and must be approved by the user
//! before any agent session is spawned.

use std::collections::{HashMap, HashSet};
use std::io::Read;
use std::process::{Command, Stdio};
use std::sync::Mutex;
use std::time::{Duration, Instant};

use serde::{Deserialize, Serialize};

use crate::worktree::Worktree;

/// One session is reserved for the orchestrator; the rest stay under `policy::MAX_SESSIONS`.
pub const MAX_AGENTS: usize = 8;
pub const MAX_REQUEST_LEN: usize = 8 * 1024;
const MAX_FIELD_LEN: usize = 4 * 1024;
const PLANNER_TIMEOUT: Duration = Duration::from_secs(300);
pub const ORCHESTRATOR_ID: &str = "orchestrator";

#[derive(Debug, thiserror::Error)]
pub enum PlanError {
    #[error("invalid plan: {0}")]
    Invalid(String),
    #[error("planner failed: {0}")]
    Planner(String),
    #[error("plan not found")]
    NotFound,
    #[error("plan has not been approved")]
    NotApproved,
    #[error("plan was already approved")]
    AlreadyApproved,
    #[error("agent not found in plan: {0}")]
    UnknownAgent(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Mode {
    Parallel,
    Sequential,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AgentSpec {
    pub id: String,
    pub name: String,
    pub role: String,
    pub scope: String,
    pub task: String,
    pub acceptance: Vec<String>,
    #[serde(default)]
    pub depends_on: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Plan {
    pub summary: String,
    pub mode: Mode,
    pub agents: Vec<AgentSpec>,
}

/// JSON schema handed to `claude --json-schema`. Must match `Plan` (camelCase).
pub const PLAN_SCHEMA: &str = r#"{"type":"object","additionalProperties":false,"required":["summary","mode","agents"],"properties":{"summary":{"type":"string"},"mode":{"type":"string","enum":["parallel","sequential"]},"agents":{"type":"array","minItems":1,"maxItems":8,"items":{"type":"object","additionalProperties":false,"required":["id","name","role","scope","task","acceptance","dependsOn"],"properties":{"id":{"type":"string","pattern":"^[a-z0-9][a-z0-9-]{0,31}$"},"name":{"type":"string"},"role":{"type":"string"},"scope":{"type":"string"},"task":{"type":"string"},"acceptance":{"type":"array","items":{"type":"string"}},"dependsOn":{"type":"array","items":{"type":"string"}}}}}}}"#;

fn valid_agent_id(id: &str) -> bool {
    let b = id.as_bytes();
    !b.is_empty()
        && b.len() <= 32
        && (b[0].is_ascii_lowercase() || b[0].is_ascii_digit())
        && b.iter()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'-')
        && id != ORCHESTRATOR_ID
}

impl Plan {
    pub fn validate(&self) -> Result<(), PlanError> {
        let bad = |m: String| Err(PlanError::Invalid(m));
        if self.agents.is_empty() || self.agents.len() > MAX_AGENTS {
            return bad(format!("agent count must be 1..={MAX_AGENTS}"));
        }
        if self.summary.len() > MAX_FIELD_LEN {
            return bad("summary too long".into());
        }
        let mut ids = HashSet::new();
        for a in &self.agents {
            if !valid_agent_id(&a.id) {
                return bad(format!("bad agent id {:?}", a.id));
            }
            if !ids.insert(a.id.as_str()) {
                return bad(format!("duplicate agent id {}", a.id));
            }
            let fields = [&a.name, &a.role, &a.scope, &a.task];
            if fields
                .iter()
                .any(|f| f.trim().is_empty() || f.len() > MAX_FIELD_LEN)
                || a.acceptance.iter().any(|c| c.len() > MAX_FIELD_LEN)
                || a.acceptance.len() > 32
            {
                return bad(format!("agent {} has empty or oversized fields", a.id));
            }
        }
        for a in &self.agents {
            for d in &a.depends_on {
                if d == &a.id || !ids.contains(d.as_str()) {
                    return bad(format!("agent {} has bad dependency {d:?}", a.id));
                }
            }
        }
        if self.has_cycle() {
            return bad("dependency cycle".into());
        }
        Ok(())
    }

    fn has_cycle(&self) -> bool {
        // Kahn's algorithm: a cycle leaves nodes with unresolved in-degree.
        let mut indeg: HashMap<&str, usize> = self
            .agents
            .iter()
            .map(|a| (a.id.as_str(), a.depends_on.len()))
            .collect();
        let mut ready: Vec<&str> = indeg
            .iter()
            .filter(|(_, n)| **n == 0)
            .map(|(id, _)| *id)
            .collect();
        let mut done = 0;
        while let Some(id) = ready.pop() {
            done += 1;
            for a in &self.agents {
                if a.depends_on.iter().any(|d| d == id) {
                    let n = indeg.get_mut(a.id.as_str()).expect("known id");
                    *n -= 1;
                    if *n == 0 {
                        ready.push(&a.id);
                    }
                }
            }
        }
        done != self.agents.len()
    }

    pub fn agent(&self, id: &str) -> Result<&AgentSpec, PlanError> {
        self.agents
            .iter()
            .find(|a| a.id == id)
            .ok_or_else(|| PlanError::UnknownAgent(id.into()))
    }
}

pub fn planner_prompt(request: &str) -> String {
    format!(
        "You are the INA orchestrator planner. Break the user's request into a small team of \
         AI coding agents (1 to {MAX_AGENTS}). For each agent give a short kebab-case id, a name, \
         a role, the scope (files/areas it owns, non-overlapping where possible), the concrete \
         task, verifiable acceptance criteria, and dependsOn (ids it must wait for). Choose mode \
         \"parallel\" when agents can work at the same time, otherwise \"sequential\". Do not \
         modify any files; only return the plan.\n\nUser request:\n{request}"
    )
}

pub fn orchestrator_prompt(plan: &Plan, worktrees: &HashMap<String, Worktree>) -> String {
    let team: Vec<String> = plan
        .agents
        .iter()
        .map(|a| {
            let (branch, path) = worktrees
                .get(&a.id)
                .map(|w| (w.branch.clone(), w.path.display().to_string()))
                .unwrap_or_default();
            format!(
                "- {} ({}): {} [depends on: {}] branch `{}`, worktree {}",
                a.id,
                a.role,
                a.task,
                a.depends_on.join(", "),
                branch,
                path
            )
        })
        .collect();
    format!(
        "You are the INA orchestrator. The user approved this plan ({:?} mode): {}\n\nTeam:\n{}\n\n\
         Each agent runs in its own terminal and commits to its own branch in its own git \
         worktree; their changes do not appear in your checkout until integrated. Monitor the \
         branches (e.g. `git log HEAD..<branch>`), validate results against the acceptance \
         criteria, integrate, and report honestly. Do not do the agents' work yourself.",
        plan.mode,
        plan.summary,
        team.join("\n")
    )
}

pub fn agent_prompt(plan: &Plan, agent: &AgentSpec, branch: &str) -> String {
    let criteria: Vec<String> = agent.acceptance.iter().map(|c| format!("- {c}")).collect();
    format!(
        "You are agent \"{}\" ({}) in an INA team. Overall goal: {}\n\nYour scope: {}\n\
         Your task: {}\n\nAcceptance criteria:\n{}\n\nDepends on: {}. You work in your own git \
         worktree on branch `{}`; commit your work there and do not touch other branches. Stay \
         within your scope and report clearly when done or blocked.",
        agent.name,
        agent.role,
        plan.summary,
        agent.scope,
        agent.task,
        criteria.join("\n"),
        if agent.depends_on.is_empty() {
            "none".into()
        } else {
            agent.depends_on.join(", ")
        },
        branch
    )
}

/// Args for the non-interactive planner run. No tools, no MCP: it can only answer.
pub fn planner_args(request: &str) -> Vec<String> {
    [
        "-p",
        &planner_prompt(request),
        "--output-format",
        "json",
        "--json-schema",
        PLAN_SCHEMA,
        "--tools",
        "",
        "--strict-mcp-config",
    ]
    .iter()
    .map(|s| s.to_string())
    .collect()
}

/// Extract and validate the plan from `claude -p --output-format json` stdout.
pub fn parse_planner_output(stdout: &str) -> Result<Plan, PlanError> {
    #[derive(Deserialize)]
    struct Envelope {
        #[serde(default)]
        is_error: bool,
        #[serde(default)]
        result: Option<String>,
        structured_output: Option<Plan>,
    }
    let env: Envelope = serde_json::from_str(stdout.trim())
        .map_err(|e| PlanError::Planner(format!("unparseable output: {e}")))?;
    if env.is_error {
        return Err(PlanError::Planner(
            env.result.unwrap_or_else(|| "unknown error".into()),
        ));
    }
    let plan = env
        .structured_output
        .ok_or_else(|| PlanError::Planner("no structured output".into()))?;
    plan.validate()?;
    Ok(plan)
}

/// Run the planner to completion (blocking) with a timeout. `program` comes from the policy.
pub fn run_planner(spec: &crate::pty::SpawnSpec) -> Result<Plan, PlanError> {
    let fail = |m: String| PlanError::Planner(m);
    let mut command = Command::new(&spec.program);
    for k in &spec.env_remove {
        command.env_remove(k);
    }
    let mut child = command
        .args(&spec.args)
        .current_dir(&spec.cwd)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| fail(format!("spawn: {e}")))?;
    let drain = |mut r: Box<dyn Read + Send>| {
        std::thread::spawn(move || {
            let mut s = String::new();
            r.read_to_string(&mut s).map(|_| s)
        })
    };
    let out = drain(Box::new(child.stdout.take().expect("piped")));
    let err = drain(Box::new(child.stderr.take().expect("piped")));
    let start = Instant::now();
    let status = loop {
        if let Some(s) = child.try_wait().map_err(|e| fail(e.to_string()))? {
            break s;
        }
        if start.elapsed() > PLANNER_TIMEOUT {
            let _ = child.kill();
            let _ = child.wait();
            return Err(fail("timed out".into()));
        }
        std::thread::sleep(Duration::from_millis(200));
    };
    let stdout = out
        .join()
        .map_err(|_| fail("stdout reader panicked".into()))?;
    let stdout = stdout.map_err(|e| fail(format!("read stdout: {e}")))?;
    if !status.success() && stdout.trim().is_empty() {
        let stderr = err.join().ok().and_then(Result::ok).unwrap_or_default();
        let tail: String = stderr
            .chars()
            .rev()
            .take(500)
            .collect::<String>()
            .chars()
            .rev()
            .collect();
        return Err(fail(format!("exit {:?}: {tail}", status.code())));
    }
    parse_planner_output(&stdout)
}

struct Entry {
    workspace_id: i64,
    plan: Plan,
    /// Set on approval: each agent's isolated worktree.
    worktrees: Option<HashMap<String, Worktree>>,
}

/// An approved plan, ready to spawn.
#[derive(Debug, Clone)]
pub struct Team {
    pub workspace_id: i64,
    pub plan: Plan,
    pub worktrees: HashMap<String, Worktree>,
}

/// Plans awaiting or holding approval. The backend keeps them so agent prompts never come
/// from the frontend.
#[derive(Default)]
pub struct PlanStore {
    inner: Mutex<(u64, HashMap<u64, Entry>)>,
}

impl PlanStore {
    pub fn insert(&self, workspace_id: i64, plan: Plan) -> u64 {
        let mut g = self.inner.lock().expect("plan store poisoned");
        g.0 += 1;
        let id = g.0;
        g.1.insert(
            id,
            Entry {
                workspace_id,
                plan,
                worktrees: None,
            },
        );
        id
    }

    /// A plan still awaiting approval.
    pub fn pending(&self, id: u64) -> Result<(i64, Plan), PlanError> {
        let g = self.inner.lock().expect("plan store poisoned");
        let e = g.1.get(&id).ok_or(PlanError::NotFound)?;
        if e.worktrees.is_some() {
            return Err(PlanError::AlreadyApproved);
        }
        Ok((e.workspace_id, e.plan.clone()))
    }

    /// Record approval with every agent's worktree. Fails if already approved.
    pub fn approve(&self, id: u64, worktrees: HashMap<String, Worktree>) -> Result<(), PlanError> {
        let mut g = self.inner.lock().expect("plan store poisoned");
        let e = g.1.get_mut(&id).ok_or(PlanError::NotFound)?;
        if e.worktrees.is_some() {
            return Err(PlanError::AlreadyApproved);
        }
        e.worktrees = Some(worktrees);
        Ok(())
    }

    pub fn approved(&self, id: u64) -> Result<Team, PlanError> {
        let g = self.inner.lock().expect("plan store poisoned");
        let e = g.1.get(&id).ok_or(PlanError::NotFound)?;
        let worktrees = e.worktrees.clone().ok_or(PlanError::NotApproved)?;
        Ok(Team {
            workspace_id: e.workspace_id,
            plan: e.plan.clone(),
            worktrees,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn agent(id: &str, deps: &[&str]) -> AgentSpec {
        AgentSpec {
            id: id.into(),
            name: id.into(),
            role: "dev".into(),
            scope: "src".into(),
            task: "do it".into(),
            acceptance: vec!["tests pass".into()],
            depends_on: deps.iter().map(|d| d.to_string()).collect(),
        }
    }

    fn plan(agents: Vec<AgentSpec>) -> Plan {
        Plan {
            summary: "goal".into(),
            mode: Mode::Parallel,
            agents,
        }
    }

    #[test]
    fn accepts_valid_plan() {
        plan(vec![agent("api", &[]), agent("ui", &["api"])])
            .validate()
            .unwrap();
    }

    #[test]
    fn rejects_bad_plans() {
        let cases = [
            plan(vec![]),
            plan((0..9).map(|i| agent(&format!("a{i}"), &[])).collect()),
            plan(vec![agent("Bad Id", &[])]),
            plan(vec![agent("orchestrator", &[])]),
            plan(vec![agent("a", &[]), agent("a", &[])]),
            plan(vec![agent("a", &["missing"])]),
            plan(vec![agent("a", &["a"])]),
            plan(vec![agent("a", &["b"]), agent("b", &["a"])]),
        ];
        for p in cases {
            assert!(p.validate().is_err(), "{p:?}");
        }
    }

    #[test]
    fn parses_planner_envelope() {
        let p = plan(vec![agent("api", &[])]);
        let out = serde_json::json!({ "is_error": false, "result": "x", "structured_output": p });
        assert_eq!(parse_planner_output(&out.to_string()).unwrap(), p);

        let err = r#"{"is_error":true,"result":"auth required"}"#;
        assert!(
            matches!(parse_planner_output(err), Err(PlanError::Planner(m)) if m == "auth required")
        );
        assert!(parse_planner_output("not json").is_err());
        assert!(parse_planner_output(r#"{"is_error":false}"#).is_err());
    }

    #[test]
    fn spawning_requires_approval() {
        let store = PlanStore::default();
        let id = store.insert(1, plan(vec![agent("api", &[])]));
        assert!(matches!(store.approved(id), Err(PlanError::NotApproved)));
        assert_eq!(store.pending(id).unwrap().0, 1);
        store.approve(id, HashMap::new()).unwrap();
        assert_eq!(store.approved(id).unwrap().workspace_id, 1);
        assert!(matches!(store.pending(id), Err(PlanError::AlreadyApproved)));
        assert!(matches!(
            store.approve(id, HashMap::new()),
            Err(PlanError::AlreadyApproved)
        ));
        assert!(matches!(store.approved(id + 1), Err(PlanError::NotFound)));
    }

    #[test]
    fn prompts_carry_plan_data() {
        let p = plan(vec![agent("api", &[]), agent("ui", &["api"])]);
        let a = agent_prompt(&p, p.agent("ui").unwrap(), "ina/r/ui");
        assert!(a.contains("Depends on: api") && a.contains("- tests pass"));
        assert!(a.contains("`ina/r/ui`"));
        let wt = Worktree {
            path: "C:/w/.ina/worktrees/r-ui".into(),
            branch: "ina/r/ui".into(),
        };
        let o = orchestrator_prompt(&p, &HashMap::from([("ui".to_string(), wt)]));
        assert!(o.contains("- ui (dev)") && o.contains("branch `ina/r/ui`"));
        assert!(planner_args("hi").contains(&PLAN_SCHEMA.to_string()));
    }
}

/// Calls the real `claude` CLI (costs tokens). Run with `cargo test -- --ignored real_planner`.
#[cfg(test)]
mod real {
    #[test]
    #[ignore]
    fn real_planner() {
        let path = std::env::var_os("PATH").unwrap_or_default();
        let cwd = std::env::temp_dir();
        let args =
            super::planner_args("Build a CLI todo app in Python: 1 agent for code, 1 for tests.");
        let spec =
            crate::policy::authorize(crate::policy::Program::Claude, args, &cwd, &cwd, 0, &path)
                .unwrap();
        let plan = super::run_planner(&spec).unwrap();
        println!("{plan:#?}");
    }
}
